for values in [CONTEXTS]+[v['instructions'] for v in Q.values()]+[x for v in Q.values() for x in v['criteria'].values()]:
    assert len(values)==3 and len(set(values))==3
for i in range(3):
    request={'model':'jev-latest','state':CONTEXTS[i],'questions':{k:{'type':'choice','instructions':v['instructions'][i],'criteria':{a:d[i] for a,d in v['criteria'].items()}} for k,v in Q.items()}}
    (OUT/f'request-{i+1}.json').write_text(json.dumps(request,indent=2)+'\n')
(OUT/'wording-audit.json').write_text(json.dumps({'status':'reviewed before send','method':'Manual semantic comparison and full-field inequality across all three complete contexts, questions and option descriptions. Exact technical identifiers and alternatives preserved; prior answers are not reused.','equivalent_facts':['agent/full-Can and Can-owned scenarios/oracles','chosen reference/candidate/process architecture','design-only resource limits and cleanup','current native containment/registration/output gaps','external ownership, partial effects, deadlines and retry ambiguity','browser input/interception/sealed-events and shared-service ownership','typed raw native value/callback/fault boundaries','independent SQL provenance','CheckSnapshot strengths and producer-level classification gaps'],'limits':'Rewording and agreement do not prove bias removal, enforceability or correctness.'},indent=2)+'\n')
if '--send' in sys.argv:
    for i in range(1,4):
        started=datetime.datetime.now(datetime.timezone.utc).isoformat()
        request=urllib.request.Request('https://api.typesafe.ai/v1/systemone',data=(OUT/f'request-{i}.json').read_bytes(),headers={'Content-Type':'application/json','Authorization':'Bearer '+os.environ['TYPESAFE_API_KEY']})
        try:
            with urllib.request.urlopen(request,timeout=55) as response: body,status=response.read(),response.status
        except urllib.error.URLError as error:
            (OUT/f'transport-error-{i}.json').write_text(json.dumps({'started_utc':started,'kind':type(error).__name__,'reason':str(error.reason)},indent=2)+'\n')
            raise SystemExit('Consultation transport failed; metadata saved.')
        (OUT/f'response-{i}.json').write_bytes(body+b'\n')
        (OUT/f'response-{i}.metadata.json').write_text(json.dumps({'started_utc':started,'http_status':status},indent=2)+'\n')
        parsed=json.loads(body)
        print(json.dumps({'request':i,'model':parsed.get('model'),'answers':parsed.get('answers'),'usage':parsed.get('usage')}))
